      return `<div class="row tm-row" data-stage="${st}"><div class="icon bg-accent">${st === '17' ? 'D' : st}</div><div style="flex:1"><div class="t">${STAGES[st].name.replace(/^Module \d+ · |^Later · /, '')}</div><div class="tm-links">${links}</div></div></div>`;
